    const OP_DRAW_INDEXED_PRIMITIVE = D9WG.OP.DRAW_INDEXED_PRIMITIVE;
    const OP_DRAW_PRIMITIVE_UP = D9WG.OP.DRAW_PRIMITIVE_UP;

