    const D3DQUERYTYPE_OCCLUSION = 9;
    const D3DQUERYTYPE_TIMESTAMP = 10;
    const D3DQUERYTYPE_TIMESTAMPDISJOINT = 11;
    const D3DQUERYTYPE_TIMESTAMPFREQ = 12;

