                // GL leaves row padding and skipped pixels as they were
                const out = new Uint8Array(dataSize);
                const at = recordOffset + READ_PIXELS_HEADER_SIZE;
                out.set(bytes.subarray(at, Math.min(at + dataSize, bytes.length)));
